from pathlib import Path
import json, html
root=Path(__file__).resolve().parents[1]/'assets/demo-v1'
manifest=json.loads((root/'manifest.json').read_text())
cards=[]
for a in manifest['entries']:
    p=html.escape(a['path']); title=html.escape(a['id']);desc=html.escape(a['purpose'])
    if a['type'] in ('png','svg'):
        media=f'<a href="{p}" target="_blank"><img loading="lazy" src="{p}" alt="{desc}"></a>'
    elif a['type']=='wav': media=f'<audio controls preload="none" src="{p}"></audio>'
    else: media=f'<a href="{p}">Mở dữ liệu văn bản</a>'
    cards.append(f'<article>{media}<h3>{title}</h3><p>{desc}</p><code>{p}</code></article>')
template='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>An Linh — Thư viện assets demo v1</title>
<style>*{box-sizing:border-box}body{margin:0;background:#161c19;color:#e2dac6;font:16px/1.6 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:32px}h1{font-size:32px}h2{margin-top:40px}p{max-width:850px;color:#bbbcae}button,select,a{color:#dfcf9f}button,select{background:#28312b;border:1px solid #69715e;padding:10px;border-radius:3px;font:inherit}button:focus-visible,select:focus-visible{outline:3px solid #d6ba78}.controls{display:flex;gap:14px;flex-wrap:wrap;margin:15px 0}.stage{position:relative;width:100%;overflow:hidden;background:#080e0a}.base{width:100%;display:block}.layer{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.shadow-box{position:absolute;pointer-events:none}.shadow-box img{width:100%;height:100%}.hotspot{position:absolute;border:2px dashed #e0c07a;background:#f2c14b18;color:#fff;display:none;font-size:12px;padding:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}article{background:#222b25;border:1px solid #3a443b;padding:14px;min-width:0}article img{width:100%;height:190px;object-fit:contain;background:repeating-conic-gradient(#404640 0% 25%,#303630 0% 50%) 50%/20px 20px}article audio{width:100%}h3{margin:10px 0 0;font-size:16px}article p{font-size:14px}code{font-size:11px;overflow-wrap:anywhere}.notice{border-left:3px solid #bd9d62;padding:8px 18px;background:#252b23}</style>
<main><p>AN LINH / THƯ VIỆN TÀI NGUYÊN</p><h1>Khu tập thể An Vân — demo v1</h1><p class="notice">Bộ hình AI và hiệu ứng tạm để thử game. Đây là trang xem assets, chưa phải game điều tra hoàn chỉnh. EVP hiện dùng giọng tiếng Việt tổng hợp tạm. Âm thanh chỉ phát khi bạn nhấn nút.</p>
<div class="controls"><label>Cảnh <select id="scene"><option value="room1305">Căn 1305</option><option value="corridor">Hành lang tầng 13</option><option value="station">Bàn theo dõi tầng 12</option></select></label><button id="ghost" aria-pressed="false">Bóng người: tắt</button><button id="cctv" aria-pressed="false">Camera: tắt</button><button id="points" aria-pressed="false">Điểm bấm: tắt</button></div>
<div class="stage"><img class="base" id="base" alt="Cảnh căn hộ"><div class="shadow-box" id="shadow" hidden><img src="overlays/ov-shadow-v1.svg" alt=""></div><img class="layer" id="vignette" src="overlays/ov-vignette-v1.svg" alt="" hidden><img class="layer" id="scan" src="overlays/ov-cctv-v1.svg" alt="" hidden><div id="spots"></div></div><p id="caption"></p>
<h2>Trạng thái ô kỹ thuật</h2><div class="controls"><button data-hatch="closed">Đóng</button><button data-hatch="open">Mở — có sách</button><button data-hatch="empty">Đã lấy sách</button></div><img id="hatch" src="closeups/cl-hatch-closed-v1.png" alt="Ô kỹ thuật" style="width:100%;max-width:1000px">
<h2>Danh mục tài nguyên</h2><p><a href="README.md">Hướng dẫn thay và tạo lại</a> · <a href="manifest.json">Danh mục</a> · <a href="prompts/all-prompts.json">Prompt gốc</a></p><div class="grid">CARDS</div>
<h2>Nội dung tạm và phần còn thiếu</h2><p>Ảnh phòng ngủ/bếp riêng, giọng EVP diễn viên đọc, tiếng bước chân và các biến thể cửa/ghế chưa có. Sơ đồ là hư cấu, không theo tỷ lệ. Đọc README trước khi tích hợp.</p></main>
<script>const integration=CONFIG;const files=FILES;const $=id=>document.getElementById(id);let ghosts=false,points=false;function render(){const name=$('scene').value,s=integration.scenes[name];$('base').src=files[s.base];$('base').alt=name;$('shadow').style.cssText=`left:${s.shadow_box[0]*100}%;top:${s.shadow_box[1]*100}%;width:${s.shadow_box[2]*100}%;height:${s.shadow_box[3]*100}%;opacity:.65`;$('shadow').hidden=!ghosts;$('vignette').hidden=!ghosts;$('vignette').style.opacity='.35';$('spots').replaceChildren();for(const p of s.hotspots||[]){let b=document.createElement('button');b.className='hotspot';b.textContent=p.id;b.style.cssText=`left:${p.rect[0]*100}%;top:${p.rect[1]*100}%;width:${p.rect[2]*100}%;height:${p.rect[3]*100}%;display:${points?'block':'none'}`;b.onclick=()=>{$('caption').textContent='Điểm tương tác đề xuất: '+p.id+' — '+p.action;if(p.id==='hatch')$('hatch').scrollIntoView({behavior:'instant'});};$('spots').append(b);}$('caption').textContent=s.note||'Các điểm bấm là đề xuất, cần kiểm tra lại trong game.';}function toggle(id,on,label){$(id).setAttribute('aria-pressed',String(on));$(id).textContent=label+': '+(on?'bật':'tắt');}$('scene').onchange=render;$('ghost').onclick=()=>{ghosts=!ghosts;toggle('ghost',ghosts,'Bóng người');render()};$('points').onclick=()=>{points=!points;toggle('points',points,'Điểm bấm');render()};$('cctv').onclick=()=>{let on=$('scan').hidden;$('scan').hidden=!on;toggle('cctv',on,'Camera')};document.querySelectorAll('[data-hatch]').forEach(b=>b.onclick=()=>{$('hatch').src='closeups/cl-hatch-'+b.dataset.hatch+'-v1.png'});document.querySelectorAll('audio').forEach(a=>{a.volume=.3;a.onplay=()=>document.querySelectorAll('audio').forEach(o=>{if(o!==a)o.pause()})});render();</script></html>'''
files={a['id']:a['path'] for a in manifest['entries']}
config=json.loads((root/'integration.json').read_text())
(root/'preview.html').write_text(template.replace('CARDS',''.join(cards)).replace('CONFIG',json.dumps(config,ensure_ascii=False)).replace('FILES',json.dumps(files)),encoding='utf-8')
print('Built standalone preview.html (works with file://, no server or dependencies).')
